var TECH_TYPES=['Slashing','Thrusting','Dance Form','Elemental','Enhancement','Speed','Illusion','Manipulation','Creation','Barrier','Transformation','Custom'];

function g(id){return document.getElementById(id)}
function gv(id){var e=g(id);return e?e.value.trim():''}

function hexRgb(h){return parseInt(h.slice(1,3),16)+','+parseInt(h.slice(3,5),16)+','+parseInt(h.slice(5,7),16)}
function setAccent(hex){
  currentColor=hex;
  var r=document.documentElement;
  r.style.setProperty('--acc',hex);
  r.style.setProperty('--acc-rgb',hexRgb(hex));
}

function applyTheme(faction){
  var t=THEMES[faction]||THEMES.human;
  var r=document.documentElement;
  r.style.setProperty('--bg',t.bg);r.style.setProperty('--pan',t.pan);
  r.style.setProperty('--pan2',t.pan2);r.style.setProperty('--pan3',t.pan3);
  r.style.setProperty('--bd',t.bd);r.style.setProperty('--bd2',t.bd2);
  r.style.setProperty('--gd',t.gd);r.style.setProperty('--gdd',t.gdd);
  r.style.setProperty('--mu',t.mu);r.style.setProperty('--tx',t.tx);
  r.style.setProperty('--tx2',t.tx2);
  var win=g('knywin');if(win)win.setAttribute('data-faction',faction);
}

function applyLang(){
  var isEN=lang==='en';
  document.querySelectorAll('.i18n').forEach(function(el){
    var t=isEN?el.getAttribute('data-en'):el.getAttribute('data-th');
    if(t!=null)el.textContent=t;
  });
  document.querySelectorAll('[data-ph-en]').forEach(function(el){
    el.placeholder=isEN?el.getAttribute('data-ph-en'):el.getAttribute('data-ph-th');
  });
  var lb=g('lang-btn');if(lb)lb.textContent=isEN?'TH':'EN';
  var sm=g('seal-msg');if(sm)sm.textContent=isEN?'Sealing destiny...':'กำลังประทับตราโชคชะตา...';
  renderTraits();
  renderTctTabs();
}

function statLevel(v){
  if(v<100)return{label:'凡',en:'Ordinary',th:'ธรรมดา',color:'#786858',desc:'Below average human',descTh:'ต่ำกว่าค่าเฉลี่ยมนุษย์'};
  if(v<300)return{label:'練',en:'Trained',th:'ผ่านการฝึก',color:'#9A8060',desc:'Above average civilian',descTh:'เหนือกว่าพลเรือนทั่วไป'};
  if(v<500)return{label:'鍛',en:'Seasoned',th:'ผ่านศึก',color:'#B09040',desc:'Demon Slayer Corps standard',descTh:'มาตรฐานกองพันนักล่า'};
  if(v<700)return{label:'精',en:'Elite',th:'ระดับยอด',color:'#C9922A',desc:'Corps veteran / Named demon',descTh:'ทหารผ่านศึก / อสูรมีชื่อ'};
  if(v<850)return{label:'柱',en:'Pillar Tier',th:'ระดับเสา',color:'#9B6FAE',desc:'Hashira / Upper Demon threat',descTh:'Hashira / ภัยคุกคามอสูรชั้นสูง'};
  if(v<980)return{label:'鬼',en:'Demon-Tier',th:'ระดับอสูร',color:'#C8384A',desc:'Upper Moon / Kokushibo range',descTh:'ระดับ Upper Moon'};
  if(v<1000)return{label:'極',en:'Extreme',th:'สุดขีด',color:'#FF4444',desc:'Beyond known limits',descTh:'เกินขีดจำกัดที่รู้จัก'};
  return{label:'無',en:'Absolute',th:'ไร้ขีดจำกัด',color:'#FFD700',desc:'Surpasses all — Muzan class',descTh:'เหนือกว่าทั้งหมด ระดับ Muzan'};
}

/* Init from $1 */
var rawEl=g('knyraw');
if(rawEl&&rawEl.value.trim()){
  var dec=document.createElement('textarea');dec.innerHTML=rawEl.value.trim();
  try{initData=JSON.parse(dec.value.trim())}catch(e){}
}
curFaction=(initData&&initData.faction)||'slayer';
currentColor=(initData&&initData.charColor)||'#8B6FAE';
selTraits=(initData&&initData.traits)?initData.traits.slice():[];
techniques=(initData&&initData.techniques)?JSON.parse(JSON.stringify(initData.techniques)):[];
curScenario=(initData&&initData.scenario)||'';

/* Color picker */
var colInp=g('charColorInput');
if(colInp){
  colInp.value=currentColor;
  colInp.addEventListener('input',function(){
    document.querySelectorAll('.csw').forEach(function(s){s.classList.remove('on')});
    setAccent(this.value);
  });
}
document.querySelectorAll('.csw').forEach(function(sw){
  sw.addEventListener('click',function(){
    document.querySelectorAll('.csw').forEach(function(x){x.classList.remove('on')});
    this.classList.add('on');colInp.value=this.dataset.c;setAccent(this.dataset.c);
  });
});

/* Stats */
STATS.forEach(function(s){statVals[s.id]=(initData&&initData.stats&&initData.stats[s.id]!=null)?initData.stats[s.id]:500});
function updateSlider(inp,id){
  var v=parseInt(inp.value);statVals[id]=v;
  var pct=v/10;
  inp.style.background='linear-gradient(90deg,var(--acc) '+pct+'%,var(--pan3) '+pct+'%)';
  var lv=statLevel(v);
  var kEl=g('sk-'+id);var vEl=g('sv-'+id);var lvEl=g('slv-'+id);
  if(kEl){kEl.textContent=lv.label;kEl.style.color=lv.color}
  if(vEl)vEl.textContent=v;
  if(lvEl){
    var bd=lang==='en'?lv.en:lv.th;
    var dd=lang==='en'?lv.desc:lv.descTh;
    lvEl.innerHTML='<span class="stat-lvl-badge" style="background:'+lv.color+'">'+bd+'</span><span class="stat-lvl-desc"> · '+dd+'</span>';
  }
}
var statsEl=g('kny-stats');
if(statsEl){
  STATS.forEach(function(s){
    var v=statVals[s.id];var lv=statLevel(v);var pct=v/10;
    var nm=lang==='en'?s.en:s.th;
    var bd=lang==='en'?lv.en:lv.th;
    var dd=lang==='en'?lv.desc:lv.descTh;
    var d=document.createElement('div');d.className='kf-stat';
    d.innerHTML='<div class="stat-top">'+
      '<span class="stat-name" id="sn-'+s.id+'">'+nm+'</span>'+
      '<span class="stat-kanji" id="sk-'+s.id+'" style="color:'+lv.color+'">'+lv.label+'</span>'+
      '<span class="stat-val" id="sv-'+s.id+'">'+v+'</span>'+
      '</div>'+
      '<input type="range" id="stat-'+s.id+'" min="0" max="1000" value="'+v+'" style="background:linear-gradient(90deg,var(--acc) '+pct+'%,var(--pan3) '+pct+'%)">'+
      '<div class="stat-lvl" id="slv-'+s.id+'">'+
        '<span class="stat-lvl-badge" style="background:'+lv.color+'">'+bd+'</span>'+
        '<span class="stat-lvl-desc"> · '+dd+'</span>'+
      '</div>';
    statsEl.appendChild(d);
    var inp=d.querySelector('input[type=range]');
    inp.addEventListener('input',function(){updateSlider(this,s.id)});
  });
}
function refreshStatLabels(){
  STATS.forEach(function(s){
    var nm=lang==='en'?s.en:s.th;
    var el=g('sn-'+s.id);if(el)el.textContent=nm;
    var lv=statLevel(statVals[s.id]);
    var bd=lang==='en'?lv.en:lv.th;var dd=lang==='en'?lv.desc:lv.descTh;
    var lvEl=g('slv-'+s.id);
    if(lvEl)lvEl.innerHTML='<span class="stat-lvl-badge" style="background:'+lv.color+'">'+bd+'</span><span class="stat-lvl-desc"> · '+dd+'</span>';
  });
}

