  var tabs=g('tct-tabs');if(!tabs)return;
  tabs.innerHTML='';
  var allBtn=document.createElement('div');allBtn.className='tct'+(curTct==='all'?' on':'');
  allBtn.textContent=lang==='en'?'All · 全':'ทั้งหมด · 全';
  allBtn.addEventListener('click',function(){curTct='all';renderTctTabs();renderTraits()});
  tabs.appendChild(allBtn);
  TRAIT_CATS.forEach(function(cat){
    var btn=document.createElement('div');btn.className='tct'+(curTct===cat.id?' on':'');
    btn.textContent=lang==='en'?cat.enLabel:cat.thLabel;
    btn.addEventListener('click',function(){curTct=cat.id;renderTctTabs();renderTraits()});
    tabs.appendChild(btn);
  });
}
function renderTraits(){
  var grid=g('trait-grid');if(!grid)return;
  grid.innerHTML='';
  var desc=g('trait-desc');if(desc){desc.textContent=lang==='en'?'Hover a trait to see its description.':'วางเมาส์บน Trait เพื่อดูคำอธิบาย';desc.style.opacity='.5'}
  var allTraits=[];
  TRAIT_CATS.forEach(function(cat){
    if(curTct==='all'||curTct===cat.id){
      cat.traits.forEach(function(t){allTraits.push({t:t,cat:cat})});
    }
  });
  allTraits.forEach(function(item){
    var t=item.t;var nm=lang==='en'?t.en:t.th;
    var el=document.createElement('div');
    el.className='tr-pill'+(selTraits.indexOf(t.en)>=0?' on':'');
    el.textContent=nm;
    el.addEventListener('mouseenter',function(){
      var d=g('trait-desc');
      if(d){d.style.opacity='1';d.textContent=(lang==='en'?t.enDesc:t.thDesc)||''}
    });
    el.addEventListener('mouseleave',function(){
      var d=g('trait-desc');
      if(d){d.style.opacity='.5';d.textContent=lang==='en'?'Hover a trait to see its description.':'วางเมาส์บน Trait เพื่อดูคำอธิบาย'}
    });
    el.addEventListener('click',function(){
      var i=selTraits.indexOf(t.en);
      if(i>=0)selTraits.splice(i,1);else selTraits.push(t.en);
      this.classList.toggle('on',selTraits.indexOf(t.en)>=0);
    });
    grid.appendChild(el);
  });
}

/* Techniques */
function saveTechFields(){
  techniques.forEach(function(t,i){
    t.form=gv('tf-form-'+i);t.name=gv('tf-name-'+i);t.nameJP=gv('tf-nameJP-'+i);
    var tp=g('tf-type-'+i);t.type=tp?tp.value:'';t.desc=gv('tf-desc-'+i);
  });
}
function buildTechList(){
  var list=g('tech-list');if(!list)return;
  list.innerHTML='';
  techniques.forEach(function(tech,idx){
    var opts=TECH_TYPES.map(function(t){return'<option'+(tech.type===t?' selected':'')+'>'+t+'</option>'}).join('');
    var prefix=curFaction==='slayer'?'型 '+(idx+1):curFaction==='demon'?'術 '+(idx+1):'# '+(idx+1);
    var ph=curFaction==='slayer'?'e.g. "First Form" / 壱ノ型':curFaction==='demon'?'e.g. "Crimson Domain"':'e.g. "Swift Strike"';
    var dots='';for(var d=1;d<=5;d++){dots+='<span class="pwr-dot'+(d<=(tech.power||1)?' on':'')+'" data-d="'+d+'" data-tc="'+idx+'"></span>'}
    var pwr=lang==='en'?'Power':'พลัง';
    var card=document.createElement('div');card.className='tech-card';card.id='tc-'+idx;
    card.innerHTML=
      '<div class="tech-hdr">'+
        '<span class="tech-num">'+prefix+'</span>'+
        '<input type="text" id="tf-form-'+idx+'" value="'+(tech.form||'')+'" placeholder="'+ph+'" style="flex:1;margin:0;font-size:10px;height:26px;padding:4px 8px;border-radius:6px">'+
        '<button class="tech-del" data-tc="'+idx+'">×</button>'+
      '</div>'+
      '<div class="kf-row c2" style="margin-bottom:8px">'+
        '<div><label class="kf-lbl" style="font-size:8px">Name (EN)</label><input type="text" id="tf-name-'+idx+'" value="'+(tech.name||'')+'" placeholder="e.g. Thunderclap and Flash"></div>'+
        '<div><label class="kf-lbl" style="font-size:8px">Name (JP 漢字)</label><input type="text" id="tf-nameJP-'+idx+'" value="'+(tech.nameJP||'')+'" placeholder="e.g. 霹靂一閃"></div>'+
      '</div>'+
      '<div class="kf-row c2" style="margin-bottom:4px">'+
        '<div><label class="kf-lbl" style="font-size:8px">Type</label><select id="tf-type-'+idx+'">'+opts+'</select></div>'+
        '<div><label class="kf-lbl" style="font-size:8px">'+pwr+'</label>'+
          '<div class="pwr-row" id="tp-'+idx+'"><span class="pwr-lbl">Pwr</span>'+dots+'</div>'+
        '</div>'+
      '</div>'+
      '<div><label class="kf-lbl" style="font-size:8px">Description</label>'+
        '<textarea id="tf-desc-'+idx+'" rows="2" style="min-height:0" placeholder="Describe the technique — motion, effect, and lore...">'+(tech.desc||'')+'</textarea>'+
      '</div>';
    list.appendChild(card);
  });
  document.querySelectorAll('.pwr-dot').forEach(function(dot){
    dot.addEventListener('click',function(){
      var d=parseInt(this.dataset.d),ti=parseInt(this.dataset.tc);
      techniques[ti].power=d;
      var row=g('tp-'+ti);
      if(row)row.querySelectorAll('.pwr-dot').forEach(function(x){x.classList.toggle('on',parseInt(x.dataset.d)<=d)});
    });
  });
  document.querySelectorAll('.tech-del').forEach(function(btn){
    btn.addEventListener('click',function(){
      saveTechFields();techniques.splice(parseInt(this.dataset.tc),1);buildTechList();
    });
  });
}
buildTechList();
var addBtn=g('add-tech-btn');
if(addBtn)addBtn.addEventListener('click',function(){
  saveTechFields();
  techniques.push({form:'',name:'',nameJP:'',type:TECH_TYPES[0],power:1,desc:''});
  buildTechList();
  var list=g('tech-list');if(list&&list.lastChild)list.lastChild.scrollIntoView({behavior:'smooth',block:'nearest'});
});

/* Scenarios */
var scenGrid=g('scen-grid');
if(scenGrid){
