  if(curFaction==='slayer'){out.rank=gv('f-rank');out.breathingPath=gv('f-breathingPath');out.mentor=gv('f-mentor');out.bladeColor=gv('f-bladeColor');out.mark=gv('f-mark')}
  else if(curFaction==='demon'){out.demonTier=gv('f-demonTier');out.bloodConc=gv('f-bloodConc');out.timeAsDemon=gv('f-timeAsDemon');out.howTurned=gv('f-howTurned');out.humanMem=gv('f-humanMem');out.wisteria=gv('f-wisteria')}
